package ma.seatflow.reservation;
import ma.seatflow.shared.ApiError.*;
import ma.seatflow.shared.StreamHub;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service public class ReservationService {private final JdbcTemplate db;private final StreamHub hub;public ReservationService(JdbcTemplate db,StreamHub hub){this.db=db;this.hub=hub;}
 public record HoldRequest(long eventId,List<Long> seatIds){} public record HoldResponse(UUID token,Instant expiresAt,BigDecimal total){}
 private long user(String username){return db.queryForObject("SELECT id FROM app_user WHERE username=?",Long.class,username);}
 @Transactional public HoldResponse hold(String username,HoldRequest req){if(req.seatIds()==null||req.seatIds().isEmpty()||req.seatIds().size()>8||new HashSet<>(req.seatIds()).size()!=req.seatIds().size())throw new Bad("Choisissez entre 1 et 8 places distinctes");long owner=user(username);var event=db.queryForMap("SELECT status,public_opens_at,priority_opens_at,season_id FROM event WHERE id=?",req.eventId());if(!"PUBLISHED".equals(event.get("status")))throw new Conflict("Événement indisponible");var now=Instant.now();var pub=((java.sql.Timestamp)event.get("public_opens_at")).toInstant();if(now.isBefore(pub)){boolean priority=db.queryForObject("SELECT EXISTS(SELECT 1 FROM season_pass WHERE owner_id=? AND season_id=? AND type='PRIORITY')",Boolean.class,owner,event.get("season_id"));var start=event.get("priority_opens_at");if(!priority||start==null||now.isBefore(((java.sql.Timestamp)start).toInstant()))throw new Conflict("La réservation n'est pas encore ouverte pour ce compte");}
 var ids=new ArrayList<>(req.seatIds());Collections.sort(ids);BigDecimal total=BigDecimal.ZERO;UUID token=UUID.randomUUID();Instant expiry=now.plus(Duration.ofMinutes(10));for(long id:ids){var seat=db.queryForMap("SELECT event_id,status,price FROM event_seat WHERE id=? FOR UPDATE",id);if(((Number)seat.get("event_id")).longValue()!=req.eventId()||!"AVAILABLE".equals(seat.get("status")))throw new Conflict("Une place est indisponible ; aucune place n'a été bloquée");db.update("UPDATE seat_hold SET status='EXPIRED' WHERE event_seat_id=? AND status='ACTIVE' AND expires_at<=now()",id);var active=db.queryForObject("SELECT count(*) FROM seat_hold WHERE event_seat_id=? AND status='ACTIVE'",Long.class,id);if(active>0)throw new Conflict("Une place est déjà bloquée ; aucune place n'a été bloquée");total=total.add((BigDecimal)seat.get("price"));db.update("INSERT INTO seat_hold(event_seat_id,owner_id,token,expires_at,status) VALUES(?,?,?,?,'ACTIVE')",id,owner,token,java.sql.Timestamp.from(expiry));db.update("INSERT INTO audit_entry(actor_id,action,entity_type,entity_id) VALUES(?,'HOLD','EVENT_SEAT',?)",owner,id);}
 org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){hub.changed(req.eventId());}});return new HoldResponse(token,expiry,total);}
 @Transactional public Map<String,Object> confirm(String username,UUID token,String key,String result){long owner=user(username);db.queryForMap("SELECT id FROM app_user WHERE id=? FOR UPDATE",owner);if(key==null||key.isBlank()||key.length()>120)throw new Bad("Clé d'idempotence requise");var existing=db.queryForList("SELECT id,status,total FROM customer_order WHERE owner_id=? AND idempotency_key=?",owner,key);if(!existing.isEmpty())return existing.get(0);var holds=db.queryForList("SELECT sh.id,sh.event_seat_id,sh.expires_at,es.event_id,es.price FROM seat_hold sh JOIN event_seat es ON es.id=sh.event_seat_id WHERE sh.token=? AND sh.owner_id=? AND sh.status='ACTIVE' ORDER BY sh.event_seat_id",token,owner);if(holds.isEmpty())throw new Conflict("Blocage expiré ou introuvable");long eventId=((Number)holds.get(0).get("event_id")).longValue();for(var h:holds){var lockedSeat=db.queryForMap("SELECT status FROM event_seat WHERE id=? FOR UPDATE",h.get("event_seat_id"));if(!"AVAILABLE".equals(lockedSeat.get("status")))throw new Conflict("Place devenue indisponible");if(((java.sql.Timestamp)h.get("expires_at")).toInstant().isBefore(Instant.now()))throw new Conflict("Blocage expiré");}BigDecimal total=holds.stream().map(h->(BigDecimal)h.get("price")).reduce(BigDecimal.ZERO,BigDecimal::add);String state="success".equals(result)?"PAID":"DECLINED";long order=db.queryForObject("INSERT INTO customer_order(owner_id,event_id,hold_token,idempotency_key,status,total) VALUES(?,?,?,?,?,?) RETURNING id",Long.class,owner,eventId,token,key,state,total);db.update("INSERT INTO payment_attempt(order_id,result,external_key) VALUES(?,?,?)",order,state,UUID.randomUUID().toString());for(var h:holds){long seat=((Number)h.get("event_seat_id")).longValue();db.update("UPDATE seat_hold SET status='CONSUMED' WHERE id=?",h.get("id"));if("PAID".equals(state)){db.update("UPDATE event_seat SET status='SOLD' WHERE id=?",seat);long item=db.queryForObject("INSERT INTO order_item(order_id,event_seat_id,price) VALUES(?,?,?) RETURNING id",Long.class,order,seat,h.get("price"));db.update("INSERT INTO ticket(order_item_id,event_seat_id,event_id,owner_id,code,status) VALUES(?,?,?,?,?,'ACTIVE')",item,seat,eventId,owner,UUID.randomUUID());}db.update("INSERT INTO audit_entry(actor_id,action,entity_type,entity_id) VALUES(?,?, 'EVENT_SEAT',?)",owner,state,seat);}org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){hub.changed(eventId);}});return Map.of("id",order,"status",state,"total",total);}
 public List<Map<String,Object>> orders(String username){return db.queryForList("SELECT id,event_id,status,total,created_at FROM customer_order WHERE owner_id=? ORDER BY id DESC",user(username));}
}
